    uint32_t data = in[2];
    for(int i=0; i<4; i++) {
        uint8_t val = (data >> (i*8)) & 0xFF;
        uint64_t c = crc ^ ((uint64_t)val << 56);
        for(int j=0; j<8; j++) {
            uint64_t mask = (uint64_t)0 - (c >> 63);
            c = (c << 1) ^ (0x42F0E1EBA9EA3693ull & mask);
        }
        crc = c;
    }
    out[0] = (uint32_t)crc;
    out[1] = (uint32_t)(crc >> 32);
    out[2] = 0;
}

